<?php

declare(strict_types=1);

namespace Skir\Runtime\Tests;

use Skir\Runtime\Field;
use Skir\Runtime\Type;
use Skir\Runtime\Variant;

/**
 * Types mirroring the upstream skir-client fixtures that produced the vectors below.
 * Every expected value was generated by running the upstream TypeScript serializers.
 */
final class UpstreamVectors
{
    public static function type(string $name): Type
    {
        return match ($name) {
            'bool' => Type::bool(),
            'int32' => Type::int32(),
            'int64' => Type::int64(),
            'hash64' => Type::hash64(),
            'float32' => Type::float32(),
            'float64' => Type::float64(),
            'timestamp' => Type::timestamp(),
            'string' => Type::string(),
            'bytes' => Type::bytes(),
            'optionalString' => Type::optional(Type::string()),
            'matrix' => Type::array(Type::array(Type::int32())),
            'address' => self::address(),
            'addresses' => Type::array(self::address()),
            'status' => self::status(),
            'user' => self::user(),
        };
    }

    public static function address(): Type
    {
        return Type::struct([
            Field::value('city', 0, Type::string()),
        ]);
    }

    public static function status(): Type
    {
        return Type::enum([
            Variant::constant('free', 1),
            Variant::wrapper('premium_since', 2, Type::timestamp()),
            Variant::wrapper('trial', 3, self::address()),
            Variant::wrapper('big', 300, Type::string()),
        ]);
    }

    public static function user(): Type
    {
        return Type::struct([
            Field::value('user_id', 0, Type::int32()),
            Field::removed(1),
            Field::value('name', 2, Type::string()),
            Field::value('nickname', 3, Type::optional(Type::string())),
            Field::value('tags', 4, Type::array(Type::string())),
            Field::value('created_at', 5, Type::timestamp()),
            Field::value('avatar', 6, Type::bytes()),
            Field::value('score', 7, Type::float64()),
            Field::value('big', 8, Type::int64()),
            Field::value('hash', 9, Type::hash64()),
            Field::value('active', 10, Type::bool()),
            Field::value('status', 11, self::status()),
            Field::value('address', 12, self::address()),
            Field::value('matrix', 13, Type::array(Type::array(Type::int32()))),
        ]);
    }

